//! Browser bindings for `au2-rust-core`.
//!
//! Keep this crate thin: logic belongs in core, where the server can use it
//! and native tests cover it. This layer only converts values at the
//! JavaScript boundary. TypeScript declarations for the core types are
//! generated by tsify and land in the `.d.ts` next to the module.

use au2_rust_core::{FieldError, LIMITS, Limits, NoteDraft};
use tsify::{Ts, Tsify};
use wasm_bindgen::prelude::*;

/// Validates a draft with the same rules the server applies.
#[wasm_bindgen(js_name = validateDraft)]
pub fn validate_draft(draft: Ts<NoteDraft>) -> Result<Vec<Ts<FieldError>>, JsError> {
    let draft = draft.to_rust()?;
    draft
        .validate()
        .iter()
        .map(|error| error.into_ts().map_err(JsError::from))
        .collect()
}

/// The slug the server will assign to a note with this title.
#[wasm_bindgen]
pub fn slugify(title: &str) -> String {
    au2_rust_core::slugify(title)
}

/// Length in Unicode scalar values, the unit the limits are measured in.
#[wasm_bindgen(js_name = charCount)]
pub fn char_count(text: &str) -> usize {
    au2_rust_core::char_count(text)
}

#[wasm_bindgen]
pub fn limits() -> Result<Ts<Limits>, JsError> {
    Ok(LIMITS.into_ts()?)
}
